-- ============================================
-- LUMA — Enrichissement Thématique 9 (Donjons & Dragons) : scénarios longs
-- ============================================

update scenarios set content = '{"characters": {"gm": "le maître du jeu"}, "start_node": "n1", "nodes": {"n1": {"speaker": "gm", "text": "The first dungeon, the Sunken Crypt, looms before you. How do you approach?", "text_fr": "Le premier donjon, la Crypte Engloutie, se dresse devant toi. Comment approches-tu ?", "choices": [{"text": "Light a torch and proceed slowly.", "next": "n2"}, {"text": "Sneak in through the shadows, no torch.", "next": "n2b"}]}, "n2": {"speaker": "gm", "text": "You find an ancient key, but a skeleton guardian awakens!", "text_fr": "Tu trouves une clé ancienne, mais un gardien squelette se réveille !", "choices": [{"text": "Fight the guardian.", "next": "n3"}, {"text": "Try to sneak past with the key.", "next": "n3b"}]}, "n2b": {"speaker": "gm", "text": "In the darkness, you nearly step on a hidden trap — quick reflexes save you.", "text_fr": "Dans l''obscurité, tu manques de peu de marcher sur un piège caché — tes réflexes te sauvent.", "choices": [{"text": "Continue cautiously toward the treasure room.", "next": "n3"}]}, "n3": {"speaker": "gm", "text": "Victory! You claim the key and move to the second dungeon: the Frozen Spire.", "text_fr": "Victoire ! Tu récupères la clé et te diriges vers le second donjon : la Flèche Gelée.", "choices": [{"text": "Press onward into the cold.", "next": "n4"}]}, "n3b": {"speaker": "gm", "text": "You slip past unnoticed, key in hand, heading to the Frozen Spire.", "text_fr": "Tu te faufiles sans être remarqué, clé en main, vers la Flèche Gelée.", "choices": [{"text": "Press onward into the cold.", "next": "n4"}]}, "n4": {"speaker": "gm", "text": "A blizzard rages. Do you push through or seek shelter first?", "text_fr": "Un blizzard fait rage. Tu forces le passage ou cherches un abri d''abord ?", "choices": [{"text": "Push through, no time to waste.", "next": "n5"}, {"text": "Find shelter and wait it out.", "next": "n5b"}]}, "n5": {"speaker": "gm", "text": "You''re exhausted but reach the peak faster than expected. A final trial awaits: the Sealed Vault.", "text_fr": "Tu es épuisé mais atteins le sommet plus vite que prévu. Une dernière épreuve t''attend : le Coffre Scellé.", "choices": [{"text": "Use the key to open the vault, despite your fatigue.", "next": "n6"}]}, "n5b": {"speaker": "gm", "text": "The wait costs you time, but you arrive at the Sealed Vault fully rested.", "text_fr": "L''attente te coûte du temps, mais tu arrives au Coffre Scellé bien reposé.", "choices": [{"text": "Use the key to open the vault, fully focused.", "next": "n6"}]}, "n6": {"speaker": "gm", "text": "Inside lies the artifact you sought all along — but a final guardian spirit challenges you to a riddle.", "text_fr": "À l''intérieur repose l''artefact que tu cherchais depuis le début — mais un dernier esprit gardien te lance un défi d''énigme.", "choices": [{"text": "Answer the riddle carefully.", "next": "end_wise"}, {"text": "Try to grab the artifact and run past the spirit.", "next": "end_bold"}]}, "end_wise": {"speaker": "gm", "text": "Correct! The spirit bows and lets you claim the artifact peacefully. Your legend will be told for generations!", "text_fr": "Correct ! L''esprit s''incline et te laisse prendre l''artefact paisiblement. Ta légende sera racontée pendant des générations !", "end": true, "ending_label": "Campagne achevée avec sagesse 🧠🏆"}, "end_bold": {"speaker": "gm", "text": "A daring escape! You barely make it out, artifact in hand, spirit howling behind you.", "text_fr": "Une fuite audacieuse ! Tu t''en sors de justesse, artefact en main, l''esprit hurlant derrière toi.", "end": true, "ending_label": "Campagne achevée avec audace ⚡🏆"}}}'::jsonb, is_playable = true
where title = 'Une campagne complète sur plusieurs donjons'
  and theme_id = (select id from scenario_themes where position = 9 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"companion": "ton compagnon"}, "start_node": "n1", "nodes": {"n1": {"speaker": "companion", "text": "I... I have to confess. I''ve been reporting our movements to the enemy.", "text_fr": "Je... je dois avouer. J''ai rapporté nos déplacements à l''ennemi.", "choices": [{"text": "Why would you betray us like this?", "next": "n2"}, {"text": "I already suspected — what changed your mind now?", "next": "n2b"}, {"text": "(draw your weapon, feeling utterly betrayed)", "next": "n2c"}]}, "n2": {"speaker": "companion", "text": "They threatened my family. I had no choice... I''m so sorry.", "text_fr": "Ils ont menacé ma famille. Je n''avais pas le choix... je suis désolé.", "choices": [{"text": "Then let''s find a way to protect your family together.", "next": "n3"}, {"text": "I understand, but trust will take time to rebuild.", "next": "n3b"}]}, "n2b": {"speaker": "companion", "text": "Guilt, mostly. I couldn''t keep lying to you.", "text_fr": "Surtout la culpabilité. Je ne pouvais plus continuer à te mentir.", "choices": [{"text": "Your honesty now means something. Let''s fix this together.", "next": "n3"}]}, "n2c": {"speaker": "companion", "text": "(flinches) I understand your anger — I deserve it. But please, let me help make this right.", "text_fr": "(recule) Je comprends ta colère — je la mérite. Mais laisse-moi t''aider à réparer ça.", "choices": [{"text": "(lower your weapon slowly) One chance. Prove it.", "next": "n3c"}]}, "n3": {"speaker": "companion", "text": "Thank you... I''ll make this right, I promise.", "text_fr": "Merci... je vais réparer ça, je te le promets.", "choices": [{"text": "Let''s use your knowledge of the enemy to turn the tables.", "next": "n4"}]}, "n3b": {"speaker": "companion", "text": "That''s fair. I''ll prove myself over time.", "text_fr": "C''est juste. Je te prouverai ma valeur avec le temps.", "choices": [{"text": "Starting now — tell us everything you know about their plans.", "next": "n4"}]}, "n3c": {"speaker": "companion", "text": "(relieved) Thank you. I know exactly where their camp is.", "text_fr": "(soulagé) Merci. Je sais exactement où se trouve leur camp.", "choices": [{"text": "Then lead us there — carefully.", "next": "n4"}]}, "n4": {"speaker": "companion", "text": "Their leader plans an ambush at dawn. We could warn our allies, or turn it against them.", "text_fr": "Leur chef prépare une embuscade à l''aube. On pourrait avertir nos alliés, ou retourner ça contre eux.", "choices": [{"text": "Let''s set a counter-ambush using this intel.", "next": "end_counter"}, {"text": "Let''s just warn our allies and avoid unnecessary risk.", "next": "end_safe"}]}, "end_counter": {"speaker": "companion", "text": "The ambush turns in our favor completely. Your trust in me wasn''t misplaced.", "text_fr": "L''embuscade tourne complètement en notre faveur. Ta confiance en moi n''était pas déplacée.", "end": true, "ending_label": "Trahison transformée en victoire tactique 🎯"}, "end_safe": {"speaker": "companion", "text": "A wise, cautious choice. Our allies are safe, and I''ve earned back a piece of your trust.", "text_fr": "Un choix sage et prudent. Nos alliés sont sauvés, et j''ai regagné un peu de ta confiance.", "end": true, "ending_label": "Confiance reconstruite prudemment 💙"}}}'::jsonb, is_playable = true
where title = 'Une trahison au sein du groupe à gérer'
  and theme_id = (select id from scenario_themes where position = 9 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"boss": "le seigneur liche"}, "start_node": "n1", "nodes": {"n1": {"speaker": "boss", "text": "You''ve come far, mortal. But none survive my final chamber.", "text_fr": "Tu es venu de loin, mortel. Mais personne ne survit à ma chambre finale.", "choices": [{"text": "Attack directly with your weapon.", "next": "n2"}, {"text": "Use a spell to weaken his defenses first.", "next": "n2b"}, {"text": "Search the room for a weakness before engaging.", "next": "n2c"}]}, "n2": {"speaker": "boss", "text": "A direct assault — bold, but predictable! (he counters hard)", "text_fr": "Un assaut direct — audacieux, mais prévisible ! (il contre-attaque violemment)", "choices": [{"text": "Adapt and dodge, then strike again.", "next": "n3"}, {"text": "Retreat briefly to reassess.", "next": "n3b"}]}, "n2b": {"speaker": "boss", "text": "You dare weaken me with magic? Impressive, actually.", "text_fr": "Tu oses m''affaiblir avec de la magie ? Impressionnant, en fait.", "choices": [{"text": "Press the advantage while he''s weakened.", "next": "n3c"}]}, "n2c": {"speaker": "boss", "text": "You found the phylactery! My power wanes!", "text_fr": "Tu as trouvé le phylactère ! Mon pouvoir décline !", "choices": [{"text": "Destroy the phylactery immediately.", "next": "n3d"}]}, "n3": {"speaker": "boss", "text": "(staggers) Impressive resilience... but I''m not done yet!", "text_fr": "(vacille) Résilience impressionnante... mais je n''ai pas fini !", "choices": [{"text": "Finish him with a final decisive strike.", "next": "end_direct"}]}, "n3b": {"speaker": "boss", "text": "Running? A wise tactic, even cowards can win.", "text_fr": "Tu fuis ? Tactique judicieuse, même les lâches peuvent gagner.", "choices": [{"text": "(regroup and return with a smarter plan)", "next": "end_tactical"}]}, "n3c": {"speaker": "boss", "text": "(weakened) No... this isn''t how it should end!", "text_fr": "(affaibli) Non... ça ne devrait pas finir comme ça !", "choices": [{"text": "Finish the spell to seal his defeat.", "next": "end_magic"}]}, "n3d": {"speaker": "boss", "text": "(screams) You found my true weakness... well played, adventurer.", "text_fr": "(hurle) Tu as trouvé ma vraie faiblesse... bien joué, aventurier.", "choices": [{"text": "(watch as his power crumbles entirely)", "next": "end_smart"}]}, "end_direct": {"speaker": "boss", "text": "Impossible... defeated by sheer will.", "text_fr": "Impossible... vaincu par pure volonté.", "end": true, "ending_label": "Victoire par la force pure 💪"}, "end_tactical": {"speaker": "boss", "text": "You outsmarted me with patience... rare among adventurers.", "text_fr": "Tu m''as surpassé par la patience... rare chez les aventuriers.", "end": true, "ending_label": "Victoire par la stratégie et la patience 🧩"}, "end_magic": {"speaker": "boss", "text": "Clever... your magic was my undoing.", "text_fr": "Astucieux... ta magie a causé ma perte.", "end": true, "ending_label": "Victoire tactique par magie 🔮"}, "end_smart": {"speaker": "boss", "text": "You found my true weakness... well played, adventurer.", "text_fr": "Tu as trouvé ma vraie faiblesse... bien joué, aventurier.", "end": true, "ending_label": "Victoire la plus intelligente 🧠🏆"}}}'::jsonb, is_playable = true
where title = 'Un combat de boss final avec plusieurs stratégies possibles'
  and theme_id = (select id from scenario_themes where position = 9 and language_id = (select id from languages where code = 'en'));
